var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<IAmazonSQS>(_ =>
    new AmazonSQSClient(RegionEndpoint.USEast1));
builder.Services.AddHostedService<SqsConsumerService>();

var host = builder.Build();
await host.RunAsync();

// No WebApplication — no HTTP listener.
// Same DI, config, logging, and graceful shutdown model.

public sealed class SqsConsumerService(
    IAmazonSQS sqs,
    ILogger<SqsConsumerService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var response = await sqs.ReceiveMessageAsync(new ReceiveMessageRequest
            {
                QueueUrl = "https://sqs.us-east-1.amazonaws.com/123/orders",
                WaitTimeSeconds = 20
            }, stoppingToken);

            foreach (var message in response.Messages)
            {
                stoppingToken.ThrowIfCancellationRequested();
                // process...
            }
        }
        logger.LogInformation("SQS consumer stopped cleanly");
    }
}

